.dm-cmx-rc[aria-pressed="true"]{color:var(--dm-fg);box-shadow:inset 0 0 0 1px var(--dm-faint)}
/* the reply field: a dimmed edge at rest, one step stronger while it has the focus, and no ring */
.dm-cmx-in{position:relative}
.dm-cmx-box{display:flex;align-items:center;gap:6px;height:var(--dm-field-h);padding:0 5px 0 var(--dm-s-3);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-field-line);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-cmx-box{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.dm-cmx-box:has(input:focus){box-shadow:inset 0 0 0 1px var(--dm-field-line-strong)}
.dm-cmx-box input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:13.5px;color:var(--dm-fg)}
.dm-cmx-box input::placeholder{color:var(--dm-muted)}
.dm-cmx-go{width:30px;height:30px;border-radius:50%;background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;flex:none;transition:background var(--dm-t-fast),transform .15s}
@media (hover:hover) and (pointer:fine){.dm-cmx-go:hover{background:var(--dm-accent-2)}}
.dm-cmx-go:active{transform:scale(.94)}
.dm-cmx-go[disabled]{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring);transform:none}
@media (hover:hover) and (pointer:fine){.dm-cmx-go[disabled]:hover{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring);transform:none}}
.dm-cmx-men{bottom:46px;left:0;min-width:210px}
.dm-cmx.dm-done .dm-cmx-th,.dm-cmx.dm-done .dm-cmx-in{opacity:.45;pointer-events:none;transition:opacity .4s}
.dm-cmx-rv{font-size:12.5px;color:var(--dm-ok);display:flex;align-items:center;gap:6px}
:root:not([data-style="soft"]) .dm-cmx-c .dm-m:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 -1px 0 var(--dm-accent-mark)}

